#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


run_wizard() {

TOTAL_STAGES=8

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT"
PY="$ROOT/.venv/bin/python"
WORK="$(mktemp -d)"
ENV_FILE="$WORK/tour.env"   # keep the library's value store out of the repo
SERVER_PID=""
trap '[[ -n "$SERVER_PID" ]] && kill "$SERVER_PID" 2>/dev/null; true' EXIT

banner "Simulator tour: BPMN file → event log → cycle time → page"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Set up the Python environment"
say "The package (src/bpmopt) and its pinned dependencies live in .venv."
if [[ -x "$PY" ]]; then
  note "Found .venv, so nothing to install."
elif command -v uv >/dev/null 2>&1; then
  step "Running: uv sync --extra dev"
  uv sync --extra dev
else
  step "Running: python3 -m venv .venv && .venv/bin/pip install -e '.[dev]'"
  python3 -m venv .venv && .venv/bin/pip install -q -e '.[dev]'
fi
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Run the tests"
say "The tests are the simulator's promises. Read the names as a spec."
step "Running: .venv/bin/pytest -v"
printf '\n'
if ! "$ROOT/.venv/bin/pytest" -v --no-header -p no:cacheprovider 2>&1 | grep -E "PASSED|FAILED|ERROR|passed|failed"; then
  warn "pytest didn't run cleanly. Fix that before trusting any number below."
fi
printf '\n'
note "test_simulation.py: same seed → same log; every case starts and ends."
note "test_analysis.py:   mean cycle time = the book's sequence formula (§7.1.1)."
note "test_results.py:    the results file follows the JSON schema."
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Read the two inputs"
say "The simulator takes a BPMN file and a parameter file. Element IDs link them."
printf '\n'
step "Model: tests/fixtures/sequence.bpmn (ID → label)"
grep -oE '<bpmn:(startEvent|task|endEvent) id="[^"]+" name="[^"]+"' tests/fixtures/sequence.bpmn \
  | sed -E 's/<bpmn:([a-zA-Z]+) id="([^"]+)" name="([^"]+)"/      \1  \2  "\3"/'
printf '\n'
step "Parameters: tests/fixtures/sequence.params.toml"
sed 's/^/      /' tests/fixtures/sequence.params.toml
printf '\n'
note "Every [tasks.<ID>] must match a task ID in the model. Time unit: working days."
note "To see the model drawn, drag the .bpmn file onto https://demo.bpmn.io"
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Your experiment: change one duration"
say "Build application takes 5.5 days now, so a case takes 2 + 5.5 + 3 = 10.5 days."
say "You'll change it in a copy of the parameter file. The fixture stays untouched."
printf '\n'
BUILD_DAYS=""
until [[ "$BUILD_DAYS" =~ ^[0-9]+(\.[0-9]+)?$ ]]; do
  ask BUILD_DAYS "New duration for Build application, in days (e.g. 8):"
done
PREDICTION=""
until [[ "$PREDICTION" =~ ^[0-9]+(\.[0-9]+)?$ ]]; do
  ask PREDICTION "Before running it: what mean cycle time do you predict?"
done
sed -e "s/fixed = 5.5/fixed = $BUILD_DAYS/" -e 's/^version = .*/version = "tour-experiment"/' \
  tests/fixtures/sequence.params.toml > "$WORK/experiment.params.toml"
printf '  %s✓ wrote%s %s\n' "$GREEN" "$RESET" "$WORK/experiment.params.toml"
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Simulate it from Python"
say "This is the whole API. Four calls:"
read -r -d '' SIM_PY <<'PY' || true
import sys
from pathlib import Path

from bpmopt.analysis import mean_cycle_time
from bpmopt.bpmn import read_bpmn
from bpmopt.parameters import load_parameters
from bpmopt.simulation import simulate

work, prediction = Path(sys.argv[1]), float(sys.argv[2])
model = read_bpmn("tests/fixtures/sequence.bpmn")
params = load_parameters(work / "experiment.params.toml")
log = simulate(model, params, n_cases=100, seed=42)

print(log[log.case_id == 1].to_string(index=False))
log.to_csv(work / "event_log.csv", index=False)
print(f"\nMean cycle time: {mean_cycle_time(log):g} days   (you predicted {prediction:g})")
PY
printf '\n%s%s\n      mean_cycle_time(log)%s\n\n' "$DIM" "$(sed -n '/^model = /,/^log = /p' <<<"$SIM_PY" | sed 's/^/      /')" "$RESET"
step "Event log of case 1 (one row per element; start and end events take zero time):"
printf '\n'
"$PY" -c "$SIM_PY" "$WORK" "$PREDICTION" | sed 's/^/  /' || warn "the simulation failed; the Python error is above"
printf '\n'
note "Why exact? Fixed durations and no queues, so CT = T1 + T2 + T3 (book §7.1.1)."
note "Full log for all 100 cases: $WORK/event_log.csv"
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Run the notebook"
say "The notebook runs the same four calls on the original fixture, then exports"
say "web/results.json (checked against the JSON schema) for the page."
step "Running: cd notebooks && jupyter execute time_optimization.ipynb"
(cd notebooks && "$ROOT/.venv/bin/jupyter" execute time_optimization.ipynb 2>&1 | grep -v WARNING | sed 's/^/  /') \
  || warn "the notebook failed; the error is above"
printf '\n'
step "web/results.json now says:"
sed 's/^/      /' web/results.json
printf '\n'
note "Only generated_at changed. Undo with: git checkout web/results.json"
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "See the page"
PORT=8000
lsof -iTCP:"$PORT" -sTCP:LISTEN >/dev/null 2>&1 && PORT=8001
say "The page needs a static server: browsers block fetch() from a file:// page."
"$PY" -m http.server "$PORT" --bind 127.0.0.1 --directory web >/dev/null 2>&1 &
SERVER_PID=$!
sleep 1
open_url "http://127.0.0.1:$PORT/"
step "You should see the diagram and \"10.5 working days\"."
step "Same thing by hand: cd web && ../.venv/bin/python -m http.server $PORT"
pause "Press Enter to stop the server"
kill "$SERVER_PID" 2>/dev/null || true
SERVER_PID=""

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "What it can't do yet"
say "Today the simulator runs a pure sequence with fixed durations, all cases at t=0."
printf '\n'
step "XOR / AND gateways and rework loops → ticket 03 (your real model needs this)"
step "Lanes as resource pools, arrivals, waiting time → ticket 04"
step "Random (triangular) durations, case attributes → ticket 07"
step "The real as-is model and its parameters → tickets 06 and 10"
printf '\n'
note "Cheat sheet: read_bpmn → load_parameters → simulate → mean_cycle_time."
note "Your experiment files stay in $WORK"
pause

finish
}

run_wizard "$@"; exit
